    test('Generated table definitions across multiple builds', async () => {
        const project = new Project()

        project.addFile({
            path: 'src/fluent/acl.now.ts',
            content: `import { Acl, Table } from '@servicenow/sdk/core'

export const test_table = Table({
    name: 'test_table',
    schema: {},
})

Acl({
    $id: Now.ID['abc'],
    type: 'record',
    table: 'test_table',
    field: 'short_description',
    operation: 'read',
    script: '',
})`,
        })

        const diagnostics = await project.getDiagnostics()
        expect(diagnostics).toHaveLength(1)
        expect(diagnostics[0].message).toBe(
            `Type '"short_description"' is not assignable to type 'SystemColumns | "*"'.`
        )
    })

    test('Invalid column name on index array throws diagnostic error', async () => {
        const project = ctx.createProject({
            rootDir: path.resolve(__dirname, 'project'),
            config: TEST_CONFIG,
            packageJson: TEST_PACKAGE_JSON,
        })
        const CODE = `import { Table, StringColumn } from '@servicenow/sdk/core'

export const x_test_document_id = Table({
    name: 'x_test_document_id',
    schema: {
        name: StringColumn({ label: 'Name' }),
    },
    index: [
        {
            element: 'non_existing',
            name: 'my_index',
            unique: true,
        },
    ],
})
`
        const file = project.addFile({ path: 'table.now.ts', content: CODE })

        const diagnostics = await file.getDiagnostics()
        expect(diagnostics).toHaveLength(1)
        expect(diagnostics[0].level).toEqual(Diagnostic.Level.Error)
        expect(diagnostics[0].message).toEqual("Column 'non_existing' not found in table 'x_test_document_id'")
    })

    test('Invalid column in multi-column index throws diagnostic error', async () => {
        const project = ctx.createProject({
            rootDir: path.resolve(__dirname, 'project'),
            config: TEST_CONFIG,
            packageJson: TEST_PACKAGE_JSON,
        })
        const CODE = `import { Table, StringColumn } from '@servicenow/sdk/core'

export const x_test_document_id = Table({
    name: 'x_test_document_id',
    schema: {
        name: StringColumn({ label: 'Name' }),
        status: StringColumn({ label: 'Status' }),
    },
    index: [
        {
            element: ['name', 'non_existing', 'status'],
            name: 'my_composite_index',
            unique: true,
        },
    ],
})
`
        const file = project.addFile({ path: 'table.now.ts', content: CODE })
        const diagnostics = await file.getDiagnostics()
        expect(diagnostics).toHaveLength(1)
        expect(diagnostics[0].message).toEqual("Column 'non_existing' not found in table 'x_test_document_id'")
    })
